package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
final class SettingsSheet {
 static void show(Context c){NativeSheet sheet=new NativeSheet(c,"Configurações");HorizontalScrollView strip=new HorizontalScrollView(c);strip.setHorizontalScrollBarEnabled(false);LinearLayout tabs=new LinearLayout(c);strip.addView(tabs);sheet.body.addView(strip);LinearLayout panel=new LinearLayout(c);panel.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(panel);String[] names={"Conta","Aparência","Notificações","Privacidade"};Button[] buttons=new Button[4];for(int i=0;i<4;i++){int tab=i;Button b=action(c,names[i],false);buttons[i]=b;tabs.addView(b,new LinearLayout.LayoutParams(NativeSheet.dp(c,130),NativeSheet.dp(c,48)));b.setOnClickListener(v->{for(Button button:buttons)AppStyle.button(button,button==b);render(c,panel,tab,sheet);});}render(c,panel,0,sheet);AppStyle.button(buttons[0],true);sheet.show();}
 private static void render(Context c,LinearLayout panel,int tab,NativeSheet sheet){panel.removeAllViews();android.content.SharedPreferences p=c.getSharedPreferences("batcaverna",0);
  if(tab==0){Button stats=action(c,"Minhas estatísticas",false);panel.addView(stats);stats.setOnClickListener(v->JourneySheet.statistics(c));panel.addView(NativeSheet.text(c,"Sua conta",22,0xfff3eafa));String email=p.getString("user_email","");if(!email.isEmpty())panel.addView(NativeSheet.text(c,email,13,0xffb4a7c4));Button password=action(c,"Alterar senha",false);panel.addView(password);password.setOnClickListener(v->AccountSettingsDialog.show(c,true));Button address=action(c,"Alterar e-mail",false);panel.addView(address);address.setOnClickListener(v->AccountSettingsDialog.show(c,false));Button steam=action(c,"Minha Steam",false);panel.addView(steam);steam.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).destination(6);});Button profile=action(c,"Editar perfil e destaques",true);panel.addView(profile);profile.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).destination(4);});Button exit=action(c,"↪ Sair da conta",false);exit.setTextColor(0xffffa8b5);panel.addView(exit);exit.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).logout();});}
  if(tab==1){panel.addView(NativeSheet.text(c,"Aparência",22,0xfff3eafa));String[] labels={"Foto de perfil","Capa do perfil","Fundo do perfil"},fields={"avatar_url","banner_url","fundo"};for(int i=0;i<labels.length;i++){String field=fields[i];Button b=action(c,"Trocar "+labels[i],false);panel.addView(b);b.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).chooseImage(field);});}toggle(c,panel,"Capas compactas","compact",false);toggle(c,panel,"Atualizar conversas automaticamente","chat_sync",true);Button clear=action(c,"Limpar cache de imagens",false);panel.addView(clear);clear.setOnClickListener(v->{AccountImageLoader.clear();Toast.makeText(c,"Cache limpo",Toast.LENGTH_SHORT).show();});Button hide=action(c,p.getBoolean("hide_background",false)?"Mostrar fundo neste aparelho":"Ocultar fundo neste aparelho",false);panel.addView(hide);hide.setOnClickListener(v->{p.edit().putBoolean("hide_background",!p.getBoolean("hide_background",false)).apply();sheet.dialog.dismiss();((MainActivity)c).openProfile();});}
  if(tab==2){Button preferences=action(c,"Preferências por tipo (site e APK)",true);panel.addView(preferences);preferences.setOnClickListener(v->CollectionSheet.preferences(c));panel.addView(NativeSheet.text(c,"Notificações",22,0xfff3eafa));panel.addView(NativeSheet.text(c,"Alertas de mensagens e atividades",14,0xffb4a7c4));Button enable=action(c,p.getBoolean("native_alerts",false)?"Desativar alertas no aparelho":"Ativar alertas no aparelho",true);panel.addView(enable);enable.setOnClickListener(v->{((MainActivity)c).toggleNotifications();render(c,panel,tab,sheet);});Button inbox=action(c,"Abrir central de notificações",false);panel.addView(inbox);inbox.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).destination(8);});TextView status=NativeSheet.text(c,com.google.firebase.FirebaseApp.getApps(c).isEmpty()?"Firebase ainda não configurado neste APK.":p.getString("push_status","Firebase configurado. Ative os alertas e configure o envio no Supabase."),12,0xffa79bb8);panel.addView(status);}
  if(tab==3){panel.addView(NativeSheet.text(c,"Privacidade e segurança",22,0xfff3eafa));panel.addView(NativeSheet.text(c,"Acesso a perfis e conteúdo segue as regras de amizade e bloqueio da sua conta.",14,0xffb4a7c4));Button friends=action(c,"Gerenciar amigos",false);panel.addView(friends);friends.setOnClickListener(v->{sheet.dialog.dismiss();((MainActivity)c).destination(2);});Button blocked=action(c,"Usuários bloqueados",false);panel.addView(blocked);blocked.setOnClickListener(v->blocked(c));}
  panel.addView(NativeSheet.text(c,"BatCaverna Native • "+BuildConfig.VERSION_NAME,11,0xff84778f));
 }
 private static void toggle(Context c,LinearLayout body,String text,String key,boolean def){Switch s=new Switch(c);s.setText(text);s.setTextColor(0xffdcd1e8);s.setPadding(0,16,0,16);s.setChecked(c.getSharedPreferences("batcaverna",0).getBoolean(key,def));body.addView(s);s.setOnCheckedChangeListener((b,on)->c.getSharedPreferences("batcaverna",0).edit().putBoolean(key,on).apply());}
 private static void blocked(Context c){NativeSheet s=new NativeSheet(c,"Usuários bloqueados");TextView state=NativeSheet.text(c,"Carregando…",13,0xffb8a8cd);s.body.addView(state);s.show();new AccountRepository(c).blocked((rows,error)->{if(error!=null){state.setText(error);return;}state.setText(rows.length()==0?"Nenhum usuário bloqueado.":rows.length()+" usuários bloqueados");for(int i=0;i<rows.length();i++){String id=rows.optJSONObject(i).optString("bloqueado_id");Button b=action(c,"Desbloquear usuário • "+id.substring(Math.max(0,id.length()-6)),false);s.body.addView(b);b.setOnClickListener(v->{b.setEnabled(false);new AccountRepository(c).unblock(id,(r,e)->{if(e!=null){state.setText(e);return;}b.setVisibility(android.view.View.GONE);state.setText("Usuário desbloqueado.");});});}});}
 private static Button action(Context c,String label,boolean primary){Button b=new Button(c);b.setText(label);AppStyle.button(b,primary);return b;}
}
